CREATE TABLE IF NOT EXISTS budget_overrides (id VARCHAR(36) PRIMARY KEY, team_id VARCHAR(36) NOT NULL, member_id VARCHAR(36) NOT NULL, pool_id VARCHAR(36) NULL, daily_units BIGINT NOT NULL, created_by VARCHAR(36) NOT NULL, reason VARCHAR(240) NOT NULL, created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, replaces_id VARCHAR(36) NULL, revoked_at BIGINT NULL, revoked_by VARCHAR(36) NULL, revocation_reason VARCHAR(240) NULL, CONSTRAINT fk_budget_overrides_team_id__id FOREIGN KEY (team_id) REFERENCES teams(id) ON UPDATE RESTRICT, CONSTRAINT fk_budget_overrides_member_id__id FOREIGN KEY (member_id) REFERENCES members(id) ON UPDATE RESTRICT);
CREATE INDEX override_member_active ON budget_overrides (team_id, member_id, revoked_at, expires_at);
CREATE INDEX override_member_page ON budget_overrides (team_id, member_id, created_at, id);